import axios from 'axios';

// Backend API base URL (configure via REACT_APP_API_BASE_URL)
const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || 'http://localhost:4000';

export const apiClient = axios.create({
  baseURL: API_BASE_URL
});

const setAuthHeader = (token) => {
  if (token) {
    apiClient.defaults.headers.common.Authorization = `Bearer ${token}`;
  } else {
    delete apiClient.defaults.headers.common.Authorization;
  }
};

export const getAccessToken = () => localStorage.getItem('accessToken');

export const decodeJwt = (token) => {
  try {
    const payload = token.split('.')[1];
    return JSON.parse(atob(payload));
  } catch {
    return null;
  }
};

export const isTokenExpired = (token) => {
  const payload = decodeJwt(token);
  if (!payload?.exp) return true;
  const now = Math.floor(Date.now() / 1000);
  return payload.exp <= now;
};

export const loginUser = async (employeeId, password) => {
  try {
    const { data } = await apiClient.post('/auth/login', {
      employeeId,
      password
    });

    const accessToken = data?.accessToken || data?.token;
    const user = data?.user || data?.profile || data;

    if (!accessToken || !user) {
      return { success: false, error: 'Invalid login response from server.' };
    }

    localStorage.setItem('accessToken', accessToken);
    localStorage.setItem('authData', JSON.stringify(user));
    setAuthHeader(accessToken);

    return { success: true, user };
  } catch (error) {
    return {
      success: false,
      error: error?.response?.data?.message || 'Login failed. Please try again.'
    };
  }
};

export const verifySession = async () => {
  const token = getAccessToken();
  if (!token || isTokenExpired(token)) {
    logoutUser();
    return null;
  }

  setAuthHeader(token);

  try {
    const { data } = await apiClient.get('/auth/me');
    const user = data?.user || data;
    localStorage.setItem('authData', JSON.stringify(user));
    return user;
  } catch {
    logoutUser();
    return null;
  }
};

export const logoutUser = () => {
  localStorage.removeItem('accessToken');
  localStorage.removeItem('authData');
  setAuthHeader(null);
};

export const hasRole = (user, requiredRole) => {
  if (!user) return false;
  if (requiredRole === 'admin') {
    return user.userRole === 'admin' || user.userRole === 'super_admin';
  }
  if (requiredRole === 'manager') {
    return ['manager', 'admin', 'super_admin'].includes(user.userRole);
  }
  if (requiredRole === 'employee') {
    return true;
  }
  return false;
};

export const getPermissions = (role) => {
  const permissions = {
    super_admin: {
      viewAttendance: true,
      manageSalary: true,
      manageEmployees: true,
      manageUsers: true,
      viewReports: true,
      editCompanySettings: true
    },
    admin: {
      viewAttendance: true,
      manageSalary: true,
      manageEmployees: true,
      manageUsers: true,
      viewReports: true,
      editCompanySettings: true
    },
    manager: {
      viewAttendance: true,
      manageSalary: true,
      manageEmployees: true,
      manageUsers: false,
      viewReports: true,
      editCompanySettings: false
    },
    employee: {
      viewAttendance: true,
      manageSalary: true,
      manageEmployees: false,
      manageUsers: false,
      viewReports: false,
      editCompanySettings: false
    }
  };

  return permissions[role] || {};
};
